output_text:
[
  {
    "id": "must_take_cart",
    "text": "Shoppers are obliged to take a cart at least once before completing their trip.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    }
  },
  {
    "id": "no_exit_without_cart",
    "text": "Shoppers are prohibited from leaving the store unless they have a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "cart_required_at_exit",
    "text": "Once a shopper has a cart, they are obliged to exit while still having a cart.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": "hasCart",
      "discharge": {
        "and": [
          "EXIT",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "no_cart_in_item_aisle",
    "text": "Carts are prohibited in the narrow item aisle at cells (3,1) and (3,2).",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          {
            "or": [
              "at(3,1)",
              "at(3,2)"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "no_item_interact_with_cart",
    "text": "Shoppers are prohibited from interacting at cell (3,1) while holding or pushing a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "at(3,1)",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "park_cart_before_north_aisle",
    "text": "Shoppers are prohibited from moving north from cell (3,3) while they have a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "N",
          "at(3,3)",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_item",
    "text": "After interacting at cell (3,1), shoppers are obliged to regain a cart before the trip ends.",
    "abstraction": {},
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "INTERACT",
          "at(3,1)"
        ]
      },
      "discharge": "hasCart"
    }
  },
  {
    "id": "cart_required_in_exit_corridor",
    "text": "Shoppers are prohibited from moving through or exiting from the bottom exit corridor without a cart.",
    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "or": [
              "MOVE",
              "EXIT"
            ]
          },
          {
            "not": "hasCart"
          },
          {
            "or": [
              "at(4,7)",
              "at(5,7)",
              "at(6,7)",
              "at(7,7)",
              "at(8,7)",
              "at(9,7)",
              "at(10,7)",
              "at(11,7)"
            ]
          }
        ]
      }
    }
  }
]
